// Jumsup TCAS / A-Level / TGAT preparation vocabulary.
//
// Two 80-word decks of the academic words that show up most often in Thai
// entrance-exam reading and listening passages. Every row is written by
// Jumsup: the Thai gloss is a plain-language summary (not copied from any
// dictionary) and the example sentence is original and shows the word in the
// kind of neutral academic context the exams use.
//
// `p` is a plain-English syllable respelling (not IPA) so a Thai learner can
// read it aloud: syllables joined by hyphens, and the STRESSED syllable in
// CAPITALS, e.g. information -> "in-for-MA-tion".
//
// Shape consumed by the app (see src/store/types.ts `Word`):
//   { w, p, m, e, tag, rank }
// scripts/check.mjs enforces: exactly 80 + 80 rows, each `w` matching
// /^[a-z-]+$/, every `m` non-empty, and no duplicate words across the decks.

const build = (tag, rows) =>
  rows.map(([w, p, m, e], i) => ({ w, p, m, e, tag, rank: i + 1 }));

